import{_ as t,o as r,c as a,a3 as o}from"./chunks/framework.DxEvSMU4.js";const u=JSON.parse('{"title":"K6 安全基礎與風險控管","description":"","frontmatter":{},"headers":[],"relativePath":"know/k6-security.md","filePath":"know/k6-security.md","lastUpdated":1793033429000}'),l={name:"know/k6-security.md"};function i(n,e,d,s,c,p){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="k6-安全基礎與風險控管" tabindex="-1">K6 安全基礎與風險控管 <a class="header-anchor" href="#k6-安全基礎與風險控管" aria-label="Permalink to &quot;K6 安全基礎與風險控管&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本章屬性</p><ul><li>等級: ● 必要</li><li>狀態: 可閱讀 (部分資料待核對)</li><li>資料基準日: 2026-10-27</li><li>待查證: OWASP LLM Top 10 2026 官方 PDF 的版次頁仍寫「發布日期待定」, 發布日以官方網頁標示的 2026-08-03 為準; 「研究 1」「研究 2」為內部研究紀錄, 非公開來源; 文中的類比為整理者所寫, 不代表技術上完全等同</li></ul></div><p><strong>結論</strong>: 地端 AI 最有效的安全措施有四項: 不對網際網路開放, 鎖定版本, 縮小權限, 能還原. 這四項成本低, 且能涵蓋 2026 年已知的主要攻擊途徑.</p><div class="tip custom-block"><p class="custom-block-title">本章常見名詞</p><table tabindex="0"><thead><tr><th>詞</th><th>意思</th></tr></thead><tbody><tr><td>127.0.0.1</td><td>代表「這台電腦自己」的網路位址, 只有本機的程式連得到</td></tr><tr><td>連接埠轉發 (port forwarding)</td><td>在路由器上設定, 讓網際網路上的連線轉進家中或公司內的某台機器</td></tr><tr><td>反向代理 (reverse proxy)</td><td>站在服務前面代收請求的程式, 可加上 HTTPS 與速率限制</td></tr><tr><td>SSO</td><td>單一登入, 一組帳號登入多個服務</td></tr><tr><td>容器 (container) 與映像 (image)</td><td>映像是把程式與執行環境打包好的檔案; 容器是由映像啟動, 正在執行的個體</td></tr><tr><td>摘要值 (digest)</td><td>依映像內容計算出的指紋, 內容一改就不同</td></tr><tr><td>沙箱 (sandbox)</td><td>讓程式在隔離環境中執行, 碰不到外面的系統</td></tr><tr><td>root</td><td>系統中權限最高的帳號</td></tr><tr><td>CVE 與 CISA KEV</td><td>CVE 是公開漏洞的編號; KEV 是美國 CISA 維護的「已知遭實際利用的漏洞」清單</td></tr><tr><td>護欄 (guardrail)</td><td>另外檢查輸入或輸出是否有問題的機制, 常是一個小型分類模型</td></tr></tbody></table><p>完整詞彙見<a href="/lanai-handbook/ref/glossary">術語對照</a>.</p></div><h2 id="k6-1-網路暴露與存取控制" tabindex="-1">K6.1 網路暴露與存取控制 <a class="header-anchor" href="#k6-1-網路暴露與存取控制" aria-label="Permalink to &quot;K6.1 網路暴露與存取控制&quot;">​</a></h2><p>服務開在哪裡, 決定了誰連得到. 可以想成住家的門: 服務只綁 127.0.0.1, 等於只有自己房間能用; 只開放內網, 等於家人都能進出; 用連接埠轉發開到網際網路, 則是把大門直接開向街上, 路過的人都能來敲門.</p><table tabindex="0"><thead><tr><th>使用情境</th><th>做法</th></tr></thead><tbody><tr><td>單人</td><td>服務只綁 127.0.0.1</td></tr><tr><td>家庭或小團隊</td><td>只開放內網, 加上介面本身的帳號系統</td></tr><tr><td>需要 HTTPS</td><td>加反向代理: Nginx (內建速率限制, 來源: nginx 文件 <code>limit_req</code> 模組) 或 Caddy (預設自動取得並更新憑證, 來源: Caddy 文件 Automatic HTTPS; 設定較簡單屬整理者判斷)</td></tr><tr><td>10 人以上, 或已有其他自架服務</td><td>才考慮 Keycloak 或 Authentik 這類 SSO</td></tr></tbody></table><p><strong>不要</strong>用連接埠轉發把服務直接開到網際網路. SentinelLABS (SentinelOne) 與 Censys 在 293 天的掃描中觀察到 130 個國家共 175,108 台暴露的 Ollama 主機 (來源: SentinelLABS 研究報告); 2026 年 n8n 於 Shadowserver 2026-02-05 的統計中仍有 24,607 台易受攻擊 (來源: SC Media); Langflow 的 CVE-2026-33017 與 CVE-2026-0770 都已列入 CISA KEV (來源: BleepingComputer 報導; 另見 <a href="/lanai-handbook/know/k5-tools-agents">K5</a>). 這幾件事屬於同一類問題.</p><p>本節不寫各工具的版本號; 上表的分級為研究 2 的推論 (信心: 中高).</p><h2 id="k6-2-供應鏈-版本鎖定與映像摘要值" tabindex="-1">K6.2 供應鏈: 版本鎖定與映像摘要值 <a class="header-anchor" href="#k6-2-供應鏈-版本鎖定與映像摘要值" aria-label="Permalink to &quot;K6.2 供應鏈: 版本鎖定與映像摘要值&quot;">​</a></h2><p>容器映像的標籤 (tag, 例如 <code>latest</code> 或 <code>v1.107.0</code>) 像門牌, 可以從一棟房子拆下來換到另一棟; 摘要值則像房子本身的指紋, 內容只要改一點就對不上. 用標籤下載, 拿到的是「現在掛這塊門牌的房子」; 用摘要值下載, 拿到的一定是當初檢查過的那一棟.</p><p>2026-10-21 的 LiteLLM 事件中, Docker Hub 上的 v1.107.0, latest, main-latest, main-stable 這些標籤都曾指向惡意映像 (來源: LiteLLM 官方事故報告). 浮動標籤因此不能當作安全依據.</p><p>實務做法:</p><ol><li>容器映像以版本號或摘要值 (digest) 鎖定, 不使用 <code>latest</code>.</li><li>記錄每個元件的安裝版本與日期 (見 O2).</li><li>升級前先讀發行說明, 並跑一次 promptfoo 測試集 (M6).</li><li>模型權重優先採用 safetensors 格式, 避免載入來源不明的 pickle 檔; pickle 載入時可能執行任意程式碼 (來源: Hugging Face Pickle scanning 文件; 研究 1 亦列為風險).</li><li>發現金鑰外洩時, 依「隔離, 重建, 輪替」處理 (整理者歸納的處理順序, 見 O3).</li></ol><h2 id="k6-3-沙箱與機密管理" tabindex="-1">K6.3 沙箱與機密管理 <a class="header-anchor" href="#k6-3-沙箱與機密管理" aria-label="Permalink to &quot;K6.3 沙箱與機密管理&quot;">​</a></h2><h3 id="沙箱分級" tabindex="-1">沙箱分級 <a class="header-anchor" href="#沙箱分級" aria-label="Permalink to &quot;沙箱分級&quot;">​</a></h3><p>沙箱可以想成讓外包人員在玻璃隔間裡工作: 外面看得到他在做什麼, 但他碰不到隔間外的東西. 讓模型執行程式碼時, 程式碼可能來自模型讀到的不可信內容, 因此要放進隔間. 隔間的牆越厚, 越難突破, 但進出也越麻煩. 「容器逃逸」指程式突破容器的隔離, 碰到主機本身; 以非 root 使用者執行, 可以降低逃逸後能做的事.</p><p>以下分級為依產業慣例的推論 (信心: 中). 表中的工具都位在「容器」與「主機」之間: Docker 與 Podman 是建立和管理容器的工具, rootless 是讓它們不需要 root 權限的執行方式; gVisor 是夾在容器與主機核心之間的隔離層, 取代一般的容器執行環境 (runc), 以 runsc 執行容器. 各工具的版本號見<a href="/lanai-handbook/ref/versions">元件版本與安全公告頁</a>, 功能描述來源見本章參考來源.</p><table tabindex="0"><thead><tr><th>層級</th><th>做法</th><th>適用</th></tr></thead><tbody><tr><td>最低</td><td>一般容器 + 非 root 使用者 (<code>--user</code>) + <code>--network none</code> + 唯讀根檔案系統 (<code>--read-only</code>) + 記憶體與 CPU 上限 (<code>--memory</code>, <code>--cpus</code>) (來源: Docker 文件 docker run 與 none network driver)</td><td>所有讀者, 成本接近零</td></tr><tr><td>中階</td><td>Podman 或 Docker rootless. Podman 是與 Docker 同類的容器管理工具, 用法接近, README 稱它可由一般使用者執行, 且沒有常駐的管理 daemon (背景服務); Docker 文件稱 rootless 模式讓 daemon 與容器都以非特權使用者執行</td><td>降低容器逃逸後的權限</td></tr><tr><td>進階</td><td>gVisor (runsc) 提供系統呼叫層隔離: 容器發出的系統呼叫先由 gVisor 在使用者空間實作的核心 (Sentry) 處理, 不直接交給主機核心; 代價是部分系統呼叫尚未實作, 且每次系統呼叫的負擔較高 (來源: gVisor 文件)</td><td>多人環境</td></tr></tbody></table><p>gVisor 的效能負擔集中在特定工作. 官方效能指南指出: 負擔主要影響大量呼叫系統的應用, 每次呼叫做的事越少, 負擔占比越高; 網路與大量小型檔案操作也有負擔; 純 CPU 運算不受影響, 因為 gVisor 不模擬 CPU 指令, 因此資料處理與機器學習類工作的負擔很小. 指南也建議多數情況使用 Systrap 平台以取得較佳效能 (來源: gVisor Performance Guide). 對本手冊的用途, 沙箱裡跑的是模型產生的短程式, 不是推論本身, 效能負擔通常可以接受 (推論, 信心: 中).</p><p>Firecracker 是另一種做法: 不共用主機核心, 而是替每個工作負載開一台微型虛擬機 (microVM); 它使用 Linux KVM 建立 microVM (來源: Firecracker GitHub README). 維運成本高, 不建議手冊讀者使用 (整理者判斷).</p><p><strong>原則</strong>: 只要讓模型執行程式碼, 就必須放進沙箱.</p><h3 id="機密管理" tabindex="-1">機密管理 <a class="header-anchor" href="#機密管理" aria-label="Permalink to &quot;機密管理&quot;">​</a></h3><p>機密指密碼, API 金鑰, 資料庫帳密這類一旦外流, 別人就能冒用身分的資料. 管理機密的重點有兩個: 平時不讓機密散落在看得到的地方, 外洩時能很快換掉.</p><ul><li><code>.env</code> 檔 (權限 600, 不進版本控制) 足以應付多數讀者 (整理者建議).</li><li>Docker Compose secrets 是下一階: 機密以檔案形式掛載到容器的 <code>/run/secrets/</code>, 避免放在環境變數中 (來源: Docker 文件 Compose secrets).</li><li>SOPS 適合用 Git 管理設定的人. 它是放在設定檔與版本控制之間的命令列工具: 把設定檔中的機密欄位加密後再存進 Git, 使用時再解密. README 稱它為加密檔案的編輯器, 支援 YAML, JSON, ENV, INI 與二進位格式, 金鑰可用 age, PGP 或雲端 KMS (來源: SOPS GitHub README; 與 Git 搭配的用法屬整理者建議).</li><li>HashiCorp Vault 與 OpenBao 是獨立運作的機密管理伺服器: 機密集中存在伺服器上, 應用程式需要時再向它索取. 官方文件稱 Vault 是以身分為基礎的機密與加密管理系統, 可動態產生憑證, 並為每個機密設定租期, 到期後撤銷 (來源: HashiCorp Vault 文件 What is Vault, v1.15.x). OpenBao 自述為管理, 儲存與分發機密, 憑證與金鑰的軟體, 授權為 MPL-2.0 (來源: OpenBao GitHub README); 它是 HashiCorp 將 Vault 改為 Business Source License 後, 社群從最後一個開源版本 (1.14 分支) 分出來的專案 (來源: The New Stack 2023-12-15 報導, 二手來源). 兩者都要另外架設, 備份與維運一台伺服器, 對手冊讀者過度 (整理者判斷).</li></ul><p>真正重要的是金鑰外洩後能快速輪替. LiteLLM 2026-10 事故報告建議從頭重建映像與環境, 並輪替代理資料庫中的供應商金鑰, master key, 虛擬金鑰與資料庫密碼 (來源: LiteLLM 官方事故報告). 2026-03 事件的官方建議則是把受影響系統上的憑證全部視為已外洩並輪替, 並鎖定已知安全的版本 (來源: LiteLLM 官方部落格 2026-03-24). 「隔離, 重建, 輪替」是整理者綜合兩次建議歸納的處理順序.</p><h2 id="k6-4-基線檢核表與-owasp-2026-對照" tabindex="-1">K6.4 基線檢核表與 OWASP 2026 對照 <a class="header-anchor" href="#k6-4-基線檢核表與-owasp-2026-對照" aria-label="Permalink to &quot;K6.4 基線檢核表與 OWASP 2026 對照&quot;">​</a></h2><p>基線檢核表分三組, 隨架構逐層累加, 見<a href="/lanai-handbook/build/overview">「組裝總覽」</a>.</p><h3 id="owasp-對照" tabindex="-1">OWASP 對照 <a class="header-anchor" href="#owasp-對照" aria-label="Permalink to &quot;OWASP 對照&quot;">​</a></h3><p>OWASP (Open Worldwide Application Security Project) 定期整理各類應用的十大風險清單, 業界常用來檢查設計是否漏掉常見風險. 下表把清單中的條目對應到本手冊的做法.</p><p>OWASP Top 10 for LLM Applications 2026 於 2026-08-03 發布 (來源: OWASP GenAI Security Project 官方頁面). 下表的條目編號與名稱已用官方頁面提供下載的 PDF 核對: LLM01 提示注入, LLM02 敏感資訊揭露, LLM03 過度代理, LLM04 供應鏈, LLM05 資料與模型投毒, LLM06 無限制資源消耗, LLM07 錯誤資訊, LLM08 隱藏情境暴露, LLM09 向量與嵌入弱點, LLM10 不當輸出處理 (2026-10-27 核對). OWASP Top 10 for Agentic Applications 2026 於 2025-12-09 發布 (來源: OWASP 官方頁面), ASI 條目名稱引自 Giskard 的整理 (二手來源). 另有一份 OWASP GenAI 的《State of Agentic AI Security and Governance》v2.01 於 2026-06-01 發布 (來源: letsdatascience.com 報導, 二手來源); 該文件與 Agentic Top 10 的更新關係待核對.</p><table tabindex="0"><thead><tr><th>風險</th><th>本手冊的對應做法</th></tr></thead><tbody><tr><td>LLM03 過度代理 (Excessive Agency), ASI02, ASI03</td><td>工具權限最小化; 寫入與刪除需人工確認</td></tr><tr><td>LLM04 供應鏈, ASI04</td><td>鎖定版本與摘要值; 審核 MCP 伺服器</td></tr><tr><td>ASI05</td><td>程式碼執行放進沙箱</td></tr><tr><td>LLM08 隱藏情境暴露, ASI06</td><td>RAG 資料來源只限可信資料夾</td></tr><tr><td>LLM06 無限制資源消耗</td><td>速率與 token 上限</td></tr></tbody></table><h3 id="護欄模型的定位" tabindex="-1">護欄模型的定位 <a class="header-anchor" href="#護欄模型的定位" aria-label="Permalink to &quot;護欄模型的定位&quot;">​</a></h3><p>護欄模型是另外執行一個模型, 專門判斷輸入或輸出有沒有問題. 可以想成大樓入口的金屬探測門: 能攔下一部分問題, 但不能取代門禁, 監視器與保全.</p><p>分類器護欄不建議當作唯一防線, 理由有兩點:</p><ol><li>字元層級手法可繞過偵測. Hackett 等人 (Mindgard 與 Lancaster University, arXiv 2504.11168) 測試 6 套偵測系統, 「Emoji Smuggling」對受測的提示注入與越獄偵測器都達到 100% 攻擊成功率; 該研究測的是第一代 Meta Prompt Guard, 未測 Prompt Guard 2.</li><li>Llama Guard 4 是 Meta 發布的安全分類模型, 用來判斷對話的輸入或輸出是否屬於不安全類別. 它有 120 億參數, 權重為 BF16 (來源: Meta 模型卡與 Hugging Face 模型卡); 依參數量 x 2 位元組推估約需 24GB (算術推論), 超出硬體等級 A 至 D 的能力.</li></ol><p>地端單人環境的主要威脅是間接提示注入, 即模型讀取的文件或網頁內夾帶指令. 比護欄更有效的做法是縮小工具權限, 要求人工確認, 並把程式碼執行放進沙箱 (信心: 中). 多人對外服務時, 才值得加 Prompt Guard 2 22M 這類輕量分類器. Prompt Guard 2 是 Meta 發布, 專門偵測提示注入與越獄企圖的小模型, 放在使用者輸入進入主模型之前 (22M 參數, 基於 DeBERTa-xsmall, 上下文 512 token; 來源: Hugging Face 模型卡), 且僅當作「多一層」. LLM Guard 是 Protect AI 的開源輸入輸出檢查工具組, 儲存庫已於 2026-07-09 封存 (來源: GitHub 儲存庫), 不建議新導入.</p><h2 id="參考來源" tabindex="-1">參考來源 <a class="header-anchor" href="#參考來源" aria-label="Permalink to &quot;參考來源&quot;">​</a></h2><p>網路暴露與事故統計:</p><ul><li><a href="https://www.sentinelone.com/labs/silent-brothers-ollama-hosts-form-anonymous-ai-network-beyond-platform-guardrails" target="_blank" rel="noreferrer">SentinelLABS: Silent Brothers, Ollama Hosts Form Anonymous AI Network Beyond Platform Guardrails (175,108 台)</a></li><li><a href="https://www.scworld.com/news/cisa-adds-n8n-rce-flaw-to-list-of-known-exploited-vulnerabilities" target="_blank" rel="noreferrer">SC Media: CISA adds n8n RCE flaw to list of known exploited vulnerabilities (24,607 台)</a></li><li><a href="https://www.bleepingcomputer.com/news/security/cisa-new-langflow-flaw-actively-exploited-to-hijack-ai-workflows/" target="_blank" rel="noreferrer">BleepingComputer: CISA new Langflow flaw actively exploited (CVE-2026-33017)</a></li><li><a href="https://www.bleepingcomputer.com/news/security/cisa-orders-feds-to-patch-actively-exploited-langflow-rce-flaw/" target="_blank" rel="noreferrer">BleepingComputer: CISA orders feds to patch actively exploited Langflow RCE flaw (CVE-2026-0770)</a></li><li><a href="https://nginx.org/en/docs/http/ngx_http_limit_req_module.html" target="_blank" rel="noreferrer">nginx 文件: ngx_http_limit_req_module</a></li><li><a href="https://caddyserver.com/docs/automatic-https" target="_blank" rel="noreferrer">Caddy 文件: Automatic HTTPS</a></li></ul><p>供應鏈與機密管理:</p><ul><li><a href="https://docs.litellm.ai/blog/security-incident-oct-21-2026" target="_blank" rel="noreferrer">LiteLLM 官方部落格: Security incident Oct 21, 2026</a></li><li><a href="https://huggingface.co/docs/hub/security-pickle" target="_blank" rel="noreferrer">Hugging Face 文件: Pickle scanning</a></li><li><a href="https://docs.docker.com/reference/cli/docker/container/run/" target="_blank" rel="noreferrer">Docker 文件: docker container run</a></li><li><a href="https://docs.docker.com/engine/network/drivers/none/" target="_blank" rel="noreferrer">Docker 文件: None network driver</a></li><li><a href="https://docs.docker.com/engine/security/rootless/" target="_blank" rel="noreferrer">Docker 文件: Rootless mode</a></li><li><a href="https://docs.docker.com/compose/how-tos/use-secrets/" target="_blank" rel="noreferrer">Docker 文件: Use secrets in Compose</a></li><li><a href="https://github.com/containers/podman" target="_blank" rel="noreferrer">Podman GitHub 儲存庫</a></li><li><a href="https://gvisor.dev/docs/" target="_blank" rel="noreferrer">gVisor 文件</a></li><li><a href="https://gvisor.dev/docs/architecture_guide/performance/" target="_blank" rel="noreferrer">gVisor 文件: Performance Guide (效能負擔來源, Systrap 建議)</a></li><li><a href="https://github.com/firecracker-microvm/firecracker" target="_blank" rel="noreferrer">Firecracker GitHub 儲存庫</a></li><li><a href="https://github.com/getsops/sops" target="_blank" rel="noreferrer">SOPS GitHub 儲存庫</a></li><li><a href="https://github.com/openbao/openbao" target="_blank" rel="noreferrer">OpenBao GitHub 儲存庫</a></li><li><a href="https://developer.hashicorp.com/vault/docs/v1.15.x/what-is-vault" target="_blank" rel="noreferrer">HashiCorp Vault 文件: What is Vault (v1.15.x)</a></li><li><a href="https://thenewstack.io/meet-openbao-an-open-source-fork-of-hashicorp-vault/" target="_blank" rel="noreferrer">The New Stack: Meet OpenBao, an open source fork of HashiCorp Vault (2023-12-15, 二手來源)</a></li><li><a href="https://docs.litellm.ai/blog/security-update-march-2026" target="_blank" rel="noreferrer">LiteLLM 官方部落格: Security Update, Suspected Supply Chain Incident (2026-03-24)</a></li></ul><p>OWASP 對照與護欄模型:</p><ul><li><a href="https://genai.owasp.org/resource/owasp-genai-llm-top-10-2026/" target="_blank" rel="noreferrer">OWASP GenAI Security Project: OWASP GenAI LLM Top 10 2026 (發布日)</a></li><li><a href="https://genai.owasp.org/download/56857/?tmstv=1785822482" target="_blank" rel="noreferrer">OWASP GenAI LLM Top 10 2026 官方 PDF (條目編號與名稱)</a></li><li><a href="https://www.imperva.com/blog/owasp-llm-top-10-2026-what-changed/" target="_blank" rel="noreferrer">Imperva: OWASP LLM Top 10 2026, What Changed and Why (二手來源, 改版說明)</a></li><li><a href="https://cloudsecurityalliance.org/blog/2026/10/21/the-owasp-top-10-for-llm-applications-2026-what-changed-and-why-it-matters" target="_blank" rel="noreferrer">Cloud Security Alliance: The OWASP Top 10 for LLM Applications 2026 (二手來源, 改版說明)</a></li><li><a href="https://genai.owasp.org/resource/owasp-top-10-for-agentic-applications-for-2026/" target="_blank" rel="noreferrer">OWASP GenAI Security Project: Top 10 for Agentic Applications for 2026</a></li><li><a href="https://www.giskard.ai/knowledge/owasp-top-10-for-agentic-application-2026" target="_blank" rel="noreferrer">Giskard: OWASP Top 10 for Agentic Applications 2026 (二手來源, ASI 條目名稱)</a></li><li><a href="https://letsdatascience.com/news/owasp-releases-agentic-ai-security-report-v201-b6926a1d" target="_blank" rel="noreferrer">letsdatascience.com: OWASP releases agentic AI security report v2.01 (二手來源)</a></li><li><a href="https://arxiv.org/abs/2504.11168" target="_blank" rel="noreferrer">Hackett 等人, Bypassing LLM Guardrails (arXiv 2504.11168)</a></li><li><a href="https://arxiv.org/pdf/2504.11168" target="_blank" rel="noreferrer">arXiv 2504.11168 全文 (Emoji Smuggling 結果)</a></li><li><a href="https://dev.meta.ai/llama/docs/model-cards-and-prompt-formats/llama-guard-4" target="_blank" rel="noreferrer">Meta 文件: Llama Guard 4 模型卡</a></li><li><a href="https://huggingface.co/meta-llama/Llama-Guard-4-12B" target="_blank" rel="noreferrer">Hugging Face 模型卡: meta-llama/Llama-Guard-4-12B</a></li><li><a href="https://huggingface.co/meta-llama/Llama-Prompt-Guard-2-22M" target="_blank" rel="noreferrer">Hugging Face 模型卡: meta-llama/Llama-Prompt-Guard-2-22M</a></li><li><a href="https://github.com/protectai/llm-guard" target="_blank" rel="noreferrer">GitHub: protectai/llm-guard (2026-07-09 封存)</a></li></ul><p>內部研究紀錄與整理者判斷:</p><ul><li>「研究 1」「研究 2」為手冊整理前的內部研究紀錄, 非公開來源. 本章中「研究 2」對存取控制工具的分級, 以及「四項措施涵蓋 2026 年已知的主要攻擊途徑」的結論, 屬整理者推論 (信心: 中高), 無公開來源可佐證.</li><li>文中的類比 (住家的門, 門牌與指紋, 玻璃隔間, 金屬探測門): 整理者所寫, 無外部來源, 不應當作技術定義引用.</li><li>沙箱分級 (最低, 中階, 進階), 機密管理的取捨, 「縮小工具權限優於護欄」的判斷, 以及 SSO 的人數門檻 (10 人), 皆為整理者建議 (推論).</li></ul>',46)])])}const g=t(l,[["render",i]]);export{u as __pageData,g as default};
